// Equipment — fixtures generated by running the BOT's own modules
// (equipment-slots, survival-progression gear gates, combat-engine bonus fold).

import { describe, expect, it } from 'vitest'
import {
  PHYSICAL_EQUIPMENT_SLOTS,
  physicalEquipmentSlot,
  equippedItemId,
  clearEquipmentSlot,
  canonicalEquipmentMap,
  gearRequiredLevel,
  gearRefusal,
  personalFloorCount,
  hasTradeMastery,
  preparationReady,
  applyEquipmentBonus,
  equipItem,
  unequipSlot,
} from '../src/engine/equipment'
import { gearMap } from '../src/data'
import { createNewPlayer } from '../src/state/player'

describe('slot aliases (bot equipment-slots.js)', () => {
  it('folds legacy keys into physical slots', () => {
    expect(physicalEquipmentSlot('relic')).toBe('offhand')
    expect(physicalEquipmentSlot('amulet')).toBe('offhand')
    expect(physicalEquipmentSlot('armor')).toBe('chestplate')
    expect(physicalEquipmentSlot('WEAPON')).toBe('weapon')
    expect(PHYSICAL_EQUIPMENT_SLOTS).toEqual([
      'weapon', 'offhand', 'helmet', 'chestplate', 'boots', 'accessory', 'tool',
    ])
  })

  it('reads the offhand through its aliases and clears every pointer', () => {
    const eq: Record<string, string | null> = { offhand: null, relic: 'old_totem', amulet: null }
    expect(equippedItemId(eq, 'offhand')).toBe('old_totem')
    clearEquipmentSlot(eq, 'relic')
    expect(eq.offhand).toBeNull()
    expect(eq.relic).toBeNull()
    expect(eq.amulet).toBeNull()
  })

  it('canonical map never double-counts a legacy relic', () => {
    const canon = canonicalEquipmentMap({ weapon: 'iron_sword', relic: 'old_totem', offhand: 'iron_shield' })
    expect(canon.weapon).toBe('iron_sword')
    expect(canon.offhand).toBe('iron_shield') // explicit offhand wins over relic
  })
})

describe('gating (bot survival-progression fixtures)', () => {
  // Bot-run values: iron_sword/leather_armor/health_potion → required 1;
  // foglight_blade → 100; guardian_shield → 45 (power gate tiers).
  it('gearRequiredLevel matches bot output for V0 items', () => {
    expect(gearRequiredLevel(gearMap['iron_sword']!)).toBe(1)
    expect(gearRequiredLevel(gearMap['leather_armor']!)).toBe(1)
    expect(gearRequiredLevel(gearMap['health_potion']!)).toBe(1)
    expect(gearRequiredLevel(gearMap['foglight_blade']!)).toBe(100)
    expect(gearRequiredLevel(gearMap['guardian_shield']!)).toBe(45)
  })

  it('refusal messages match the bot verbatim', () => {
    const fog = gearMap['foglight_blade']!
    expect(gearRefusal({ level: 1, dungeonProgress: {} }, fog)).toBe(
      '🔒 Foglight Blade requires Level 100 for combat attunement. You still own it.',
    )
    expect(gearRefusal({ level: 100, dungeonProgress: {} }, fog)).toBe(
      '🔒 Foglight Blade requires 10 personally cleared dungeon floors before attunement.',
    )
    const shield = gearMap['guardian_shield']!
    expect(gearRefusal({ level: 29, dungeonProgress: {} }, shield)).toContain('requires Level 45')
    expect(gearRefusal({ level: 60, dungeonProgress: {} }, shield)).toContain('10 personally cleared dungeon floors')
    // …and with floors + a quest claim, attunement opens (V0 jobs collapsed).
    expect(
      gearRefusal(
        { level: 60, dungeonProgress: { a: { highestFloor: 6 }, b: { highestFloor: 4 } }, quests: { dailyClaimed: ['x'], milestoneClaimed: [] } },
        shield,
      ),
    ).toBeNull()
    // floors but no quest claim → preparation gate
    expect(
      gearRefusal(
        { level: 60, dungeonProgress: { a: { highestFloor: 6 }, b: { highestFloor: 4 } }, quests: { dailyClaimed: [], milestoneClaimed: [] } },
        shield,
      ),
    ).toContain('field preparation')
    // low gear never trips the gates
    expect(gearRefusal({ level: 1, dungeonProgress: {} }, gearMap['iron_sword']!)).toBeNull()
  })

  it('personalFloorCount caps at 10 distinct floors (bot grandfather rule)', () => {
    expect(personalFloorCount({ dungeonProgress: { a: { highestFloor: 6 }, b: { highestFloor: 4 } } })).toBe(10)
    expect(personalFloorCount({ dungeonProgress: { a: { highestFloor: 20 } } })).toBe(10)
    expect(personalFloorCount({ dungeonProgress: { a: { highestFloor: 3 } } })).toBe(3)
    expect(personalFloorCount({ dungeonProgress: { a: { highestFloor: 0 } } })).toBe(0)
    expect(hasTradeMastery({ level: 20, dungeonProgress: { a: { highestFloor: 10 } } })).toBe(true)
    expect(hasTradeMastery({ level: 19, dungeonProgress: { a: { highestFloor: 10 } } })).toBe(false)
  })

  it('preparation needs a claimed quest (jobs are V1)', () => {
    expect(preparationReady({ quests: { dailyClaimed: [], milestoneClaimed: [] } })).toBe(false)
    expect(preparationReady({ quests: { dailyClaimed: ['d_kill_15'], milestoneClaimed: [] } })).toBe(true)
    expect(preparationReady({})).toBe(false)
  })
})

describe('applyEquipmentBonus (bot combat-engine)', () => {
  it('folds statBonuses in and out symmetrically', () => {
    const p = {
      classId: 'warrior',
      stats: { str: 10, agi: 5, int: 2, def: 8, lck: 3 },
      hp: 150,
      maxHp: 150,
      maxMp: 30,
      mp: 30,
    }
    const item = gearMap['leather_armor']! // agi+1, def+4, maxHp+15
    applyEquipmentBonus(p, item, 1)
    expect(p.stats.agi).toBe(6)
    expect(p.stats.def).toBe(12)
    expect(p.maxHp).toBe(165)
    applyEquipmentBonus(p, item, -1)
    expect(p.stats.agi).toBe(5)
    expect(p.stats.def).toBe(8)
    expect(p.maxHp).toBe(150)
  })

  it('folds atk into the class primary stat and never goes negative', () => {
    const p = {
      classId: 'warrior', // primary str
      stats: { str: 2, agi: 5, int: 2, def: 8, lck: 3 },
      hp: 100,
      maxHp: 100,
      maxMp: 30,
      mp: 30,
    }
    applyEquipmentBonus(p, { statBonuses: { atk: 7 } as never }, 1)
    expect(p.stats.str).toBe(9)
    applyEquipmentBonus(p, { statBonuses: { str: 50 } as never }, -1)
    expect(p.stats.str).toBe(0) // clamped at 0
  })

  it('clamps current MP when maxMp shrinks', () => {
    const p = {
      classId: 'mage',
      stats: { str: 1, agi: 1, int: 10, def: 1, lck: 1 },
      hp: 80,
      maxHp: 80,
      maxMp: 50,
      mp: 50,
    }
    // unequipping a +20 maxMp item (sign −1 against a positive bonus)
    applyEquipmentBonus(p, { statBonuses: { maxMp: 20 } as never }, -1)
    expect(p.maxMp).toBe(30)
    expect(p.mp).toBe(30)
  })
})

describe('equip / unequip flow', () => {
  function fresh() {
    const p = createNewPlayer({ name: 'EquipTester', classId: 'warrior', raceId: 'human' })
    return p as unknown as {
      level: number
      inventory: string[]
      equipped: Record<string, string | null>
      stats: Record<string, number>
      hp: number
      maxHp: number
      maxMp: number
      mp: number
      classId: string
      dungeonProgress: Record<string, { highestFloor: number }>
      quests: { dailyClaimed: string[]; milestoneClaimed: string[] }
      wallet: { solars: number; gems: number }
      xp: number
      ownedCharacters: string[]
      stamina?: { current: number; max: number }
    }
  }

  it('equips iron_sword, swaps out nothing, then unequips back', () => {
    const p = fresh()
    expect(p.inventory).toContain('iron_sword')
    const r = equipItem(p, 'iron_sword')
    expect(r.ok).toBe(true)
    expect(r.slot).toBe('weapon')
    expect(p.equipped.weapon).toBe('iron_sword')
    expect(p.inventory).not.toContain('iron_sword')
    // str+4 folded in
    expect(p.stats.str).toBe(14) // warrior base 10 + 4

    const u = unequipSlot(p, 'weapon')
    expect(u.ok).toBe(true)
    expect(p.equipped.weapon).toBeNull()
    expect(p.inventory).toContain('iron_sword')
    expect(p.stats.str).toBe(10)
  })

  it('refuses consumables and unknown items', () => {
    const p = fresh()
    expect(equipItem(p, 'health_potion').ok).toBe(false)
    expect(equipItem(p, 'definitely_not_an_item').ok).toBe(false)
  })

  it('swaps: equipping leather_armor returns nothing (empty slot); second equip of same slot returns the old item', () => {
    const p = fresh()
    expect(equipItem(p, 'leather_armor').ok).toBe(true)
    // find another chestplate in inventory — starting inventory only has one,
    // so equip the weapon swap path instead: equip iron_sword then a partial-name re-equip
    const r1 = equipItem(p, 'iron_sword')
    expect(r1.ok).toBe(true)
    // simulate owning a second weapon
    p.inventory.push('iron_sword')
    const r2 = equipItem(p, 'iron_sword')
    expect(r2.ok).toBe(true)
    expect(r2.replaced).toEqual(['Iron Sword'])
    expect(p.inventory.filter((id) => id === 'iron_sword').length).toBe(1)
    // bonuses applied once (not twice for the swap)
    expect(p.stats.str).toBe(14)
  })

  it('level gate blocks high-req gear', () => {
    const p = fresh()
    p.inventory.push('foglight_blade')
    const r = equipItem(p, 'foglight_blade')
    expect(r.ok).toBe(false)
    expect(r.error).toContain('level 100')
  })
})
